def build_file_tree(filesystem):
    tree = {}
    for path in filesystem:
        parts = path.split('/')
        subtree = tree
        path_length = len(parts)
        for i, part in enumerate(parts):
            if i < path_length - 1:
                if part not in subtree:
                    subtree[part] = {}
                subtree = subtree[part]
            else:
                subtree[part] = subtree.get(part, {})
    return tree

