        self.tokens = tokens

    def is_valid(self, token):
        return token in self.tokens

    def validate_tokens(self, tokens_to_validate):
        tokens_copy = tokens_to_validate[:]
        return [f"Token {token} is valid." if self.is_valid(token) else f"Token {token} is invalid." for token in tokens_copy]

    def validate_tokens_generator(self, tokens_to_validate):
        tokens_copy = tokens_to_validate[:]
        for token in tokens_copy:
            yield f"Token {token} is valid." if self.is_valid(token) else f"Token {token} is invalid."

