class FileSystem:
    def __init__(self):
        self.nodes = {}

    def add_node(self, name, parent_name=None):
        node = FileSystemNode(name)
        self.nodes[name] = node
        if parent_name in self.nodes:
            self.nodes[parent_name].children.append(node)

    def list_children(self, name):
        children = {}
        if name in self.nodes:
            for child in self.nodes[name].children:
                children[child.name] = child
        return children

    def all_descendants(self, name):
        descendants = {}
        if name in self.nodes:
            stack = [self.nodes[name]]
            while stack:
                current = stack.pop()
                if current.name not in descendants:
                    descendants[current.name] = current
                    stack.extend(current.children)
        return descendants

