import re

def sanitize_html(input_strings):
    sanitized_data = {}
    for input_string in input_strings:
        if input_string in sanitized_data:
            continue
        tags_pattern = re.compile(r'<.*?>')
        sanitized_data[input_string] = tags_pattern.sub('', input_string)
    return sanitized_data

